G = load()

# Find where Demo 1 output appears in Demo 1 input
grid1_in = G['Demo pair 1 input']
target1 = G['Demo pair 1 output']
print("Finding Demo 1 output in Demo 1 input...")

found_positions = []
for r in range(len(grid1_in)-2):
    for c in range(len(grid1_in[0])-2):
        match = True
        for dr in range(3):
            for dc in range(3):
                if grid1_in[r+dr][c+dc] != target1[dr][dc]:
                    match = False
                    break
            if not match:
                break
        if match:
            found_positions.append((r,c))
print(f"Found at positions: {found_positions}")
